# Find smallest repeating unit
def find_pattern(seq):
    n = len(seq)
    for period in range(1, n+1):
        if n % period == 0:
            pattern = seq[:period]
            if all(seq[i] == pattern[i % period] for i in range(n)):
                return pattern, n // period
    return seq, 1

